using System.Globalization;using System.Text;using System.Xml;using Forjix.Application.Abstractions.Analytics;using Forjix.Application.Abstractions.Identity;using Forjix.Application.Abstractions.Tenancy;using Forjix.Application.Common;namespace Forjix.Application.Features.Analytics;internal sealed class AnalyticsService(ITenantDatabaseResolver resolver,IAnalyticsStoreFactory factory,ICurrentUser current,TimeProvider clock):IAnalyticsService{public async Task<DashboardView>DashboardAsync(CancellationToken ct=default){var s=await Store(ct);await using(s)return await s.DashboardAsync(clock.GetUtcNow(),ct);}public async Task<ReportView>ReportAsync(DateTimeOffset? from,DateTimeOffset? through,CancellationToken ct=default){var end=through??clock.GetUtcNow();var start=from??end.AddDays(-30);if(start>end)throw new RequestValidationException("Período inválido.");var s=await Store(ct);await using(s)return await s.ReportAsync(start,end,ct);}public async Task<ExportedReport>ExportAsync(DateTimeOffset? from,DateTimeOffset? through,string format,CancellationToken ct=default){var report=await ReportAsync(from,through,ct);return format.ToLowerInvariant() switch{"excel" or "xls"=>new(Excel(report),"application/vnd.ms-excel",$"forjix-relatorio-{DateTime.UtcNow:yyyyMMdd}.xls"),"pdf"=>new(Pdf(report),"application/pdf",$"forjix-relatorio-{DateTime.UtcNow:yyyyMMdd}.pdf"),_=>throw new RequestValidationException("Formato de exportação inválido.")};}private async Task<IAnalyticsStore>Store(CancellationToken ct){if(current.TenantId is not{}id)throw new ResourceNotFoundException("Tenant não encontrado.");return factory.Create(await resolver.ResolveByTenantIdAsync(id,ct)??throw new ResourceNotFoundException("Tenant não encontrado."));}
 private static byte[]Excel(ReportView r){var sb=new StringBuilder();using(var w=XmlWriter.Create(sb,new XmlWriterSettings{Encoding=Encoding.UTF8,Indent=true,OmitXmlDeclaration=false})){w.WriteStartElement("Workbook","urn:schemas-microsoft-com:office:spreadsheet");w.WriteAttributeString("xmlns","ss",null,"urn:schemas-microsoft-com:office:spreadsheet");w.WriteStartElement("Worksheet");w.WriteAttributeString("ss","Name",null,"Resumo");w.WriteStartElement("Table");Row(w,"Indicador","Valor");Row(w,"Faturamento",r.Revenue.ToString("F2",CultureInfo.InvariantCulture));Row(w,"Vendas",r.SaleCount.ToString(CultureInfo.InvariantCulture));Row(w,"Ticket médio",r.AverageTicket.ToString("F2",CultureInfo.InvariantCulture));Row(w,"Compras",r.PurchasesTotal.ToString("F2",CultureInfo.InvariantCulture));Row(w,"Movimentações",r.StockMovementCount.ToString(CultureInfo.InvariantCulture));w.WriteEndElement();w.WriteEndElement();w.WriteEndElement();}return Encoding.UTF8.GetBytes(sb.ToString());}private static void Row(XmlWriter w,string a,string b){w.WriteStartElement("Row");Cell(w,a);Cell(w,b);w.WriteEndElement();}private static void Cell(XmlWriter w,string value){w.WriteStartElement("Cell");w.WriteStartElement("Data");w.WriteAttributeString("ss","Type",null,"String");w.WriteString(value);w.WriteEndElement();w.WriteEndElement();}
 private static byte[]Pdf(ReportView r){var lines=new[]{"FORJIX - RELATORIO GERENCIAL",$"Periodo: {r.From:dd/MM/yyyy} a {r.Through:dd/MM/yyyy}",$"Faturamento: R$ {r.Revenue:F2}",$"Vendas: {r.SaleCount}",$"Ticket medio: R$ {r.AverageTicket:F2}",$"Compras: R$ {r.PurchasesTotal:F2}",$"Movimentacoes de estoque: {r.StockMovementCount}","","Produtos mais vendidos:"}.Concat(r.TopProducts.Take(12).Select(x=>$"{x.ProductName} - {x.Quantity:N3} un. - R$ {x.Revenue:F2}"));var content="BT /F1 12 Tf 50 790 Td "+string.Join(" Tj 0 -20 Td ",lines.Select(x=>$"({Escape(x)})"))+" Tj ET";var objects=new[]{"<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>",$"<< /Length {Encoding.ASCII.GetByteCount(content)} >>\nstream\n{content}\nendstream","<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"};var sb=new StringBuilder("%PDF-1.4\n");var offsets=new List<int>{0};for(var i=0;i<objects.Length;i++){offsets.Add(Encoding.ASCII.GetByteCount(sb.ToString()));sb.Append(CultureInfo.InvariantCulture,$"{i+1} 0 obj\n{objects[i]}\nendobj\n");}var xref=Encoding.ASCII.GetByteCount(sb.ToString());sb.Append(CultureInfo.InvariantCulture,$"xref\n0 {objects.Length+1}\n0000000000 65535 f \n");foreach(var o in offsets.Skip(1))sb.Append(CultureInfo.InvariantCulture,$"{o:0000000000} 00000 n \n");sb.Append(CultureInfo.InvariantCulture,$"trailer << /Size {objects.Length+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF");return Encoding.ASCII.GetBytes(sb.ToString());}private static string Escape(string value)=>value.Replace("\\","\\\\",StringComparison.Ordinal).Replace("(","\\(",StringComparison.Ordinal).Replace(")","\\)",StringComparison.Ordinal);}
